STORY_FIXES = [
    ("asks God to do what He has promised", "asks God to do what he has promised"),
    ("Joab's younger brother Asahel", "Joab's brother Asahel"),
    ("wearing only a simple linen ephod", "wearing a linen ephod, a priestly garment"),
    ("After four years, Absalom goes to Hebron", "After forty years, as the KJV has it (some manuscripts say four), Absalom goes to Hebron"),
]


def apply_story_fixes():
    path = ROOT / "book_content" / "02_early_history.md"
    text = path.read_text(encoding="utf-8")
    start = text.index("\n# 2 Samuel") + 1
    try:
        end = text.index("\n# ", start + 5) + 1
    except ValueError:
        end = len(text)
    section = text[start:end]
    for old, new in STORY_FIXES:
        if section.count(old) == 0 and section.count(new) >= 1:
            continue
        if section.count(old) == 0:
            print(f"story fix skipped (not found): {old!r}")
            continue
        section = section.replace(old, new)
    path.write_text(text[:start] + section + text[end:], encoding="utf-8")
    print(f"Updated {path.relative_to(ROOT)}")


